import { describe, expect, it } from "vitest"
import {
  CARD_CATEGORIES,
  CARD_STATUSES,
  CARD_TRANSITIONS,
  MAX_SPEND_LIMIT,
  TEST_BIN,
  canTransition,
  formatCardNumber,
  generateCardNumber,
  isLuhnValid,
  luhnCheckDigit,
  maskCardNumber,
  parseIssueCardInput,
  parseStatusInput,
  spendPercent,
} from "./cards"

/**
 * Every number in this file starts with the 4242 test BIN or is generated by
 * the code under test. Nothing here may resemble a real PAN.
 */

describe("luhnCheckDigit / isLuhnValid", () => {
  it("computes the digit that makes a number pass", () => {
    // 4242 4242 4242 424 → check digit 2, the classic test number.
    expect(luhnCheckDigit("424242424242424")).toBe("2")
    expect(isLuhnValid("4242424242424242")).toBe(true)
  })

  it("fails a number whose check digit is off by one", () => {
    expect(isLuhnValid("4242424242424243")).toBe(false)
    expect(isLuhnValid("4242424242424241")).toBe(false)
  })

  it("fails a number with a transposed pair", () => {
    // Luhn catches any single-digit error and most adjacent transpositions.
    expect(isLuhnValid("4242424242424422")).toBe(false)
  })

  it("rejects non-digits and too-short input", () => {
    expect(isLuhnValid("4242 4242")).toBe(false)
    expect(isLuhnValid("")).toBe(false)
    expect(isLuhnValid("4")).toBe(false)
    expect(() => luhnCheckDigit("42x")).toThrow()
  })
})

describe("generateCardNumber", () => {
  it("always starts with the test BIN, is 16 digits, and passes Luhn", () => {
    for (let i = 0; i < 200; i++) {
      const number = generateCardNumber()
      expect(number).toMatch(/^\d{16}$/)
      expect(number.startsWith(TEST_BIN)).toBe(true)
      expect(isLuhnValid(number)).toBe(true)
    }
  })

  it("is deterministic for a given random source", () => {
    let calls = 0
    const random = () => ((calls++ * 7) % 10) / 10
    const a = generateCardNumber(random)
    calls = 0
    const b = generateCardNumber(random)
    expect(a).toBe(b)
    expect(a.startsWith(TEST_BIN)).toBe(true)
    expect(isLuhnValid(a)).toBe(true)
  })

  it("survives a random source that returns exactly 1", () => {
    const number = generateCardNumber(() => 1)
    expect(number).toMatch(/^\d{16}$/)
    expect(isLuhnValid(number)).toBe(true)
  })
})

describe("maskCardNumber / formatCardNumber", () => {
  it("masks to the last four only", () => {
    expect(maskCardNumber("4242")).toBe("•••• 4242")
  })

  it("groups the one-time reveal in fours", () => {
    expect(formatCardNumber("4242424242424242")).toBe("4242 4242 4242 4242")
  })
})

describe("status state machine", () => {
  it("allows active ⇄ frozen and either to cancelled", () => {
    expect(canTransition("active", "frozen")).toBe(true)
    expect(canTransition("frozen", "active")).toBe(true)
    expect(canTransition("active", "cancelled")).toBe(true)
    expect(canTransition("frozen", "cancelled")).toBe(true)
  })

  it("treats cancelled as terminal", () => {
    expect(canTransition("cancelled", "active")).toBe(false)
    expect(canTransition("cancelled", "frozen")).toBe(false)
    expect(canTransition("cancelled", "cancelled")).toBe(false)
    expect(CARD_TRANSITIONS.cancelled).toHaveLength(0)
  })

  it("does not allow a no-op transition to the same status", () => {
    expect(canTransition("active", "active")).toBe(false)
    expect(canTransition("frozen", "frozen")).toBe(false)
  })

  it("has a transition row for every status", () => {
    for (const status of CARD_STATUSES) {
      expect(Array.isArray(CARD_TRANSITIONS[status])).toBe(true)
    }
  })
})

describe("spendPercent", () => {
  it("is a whole-number percentage of the limit", () => {
    expect(spendPercent(0, 25000)).toBe(0)
    expect(spendPercent(20000, 25000)).toBe(80)
    expect(spendPercent(20250, 25000)).toBe(81)
    expect(spendPercent(25000, 25000)).toBe(100)
    expect(spendPercent(30000, 25000)).toBe(120)
  })

  it("never divides by zero", () => {
    expect(spendPercent(100, 0)).toBe(0)
  })
})

describe("parseIssueCardInput", () => {
  const valid = {
    nickname: "Ad spend",
    merchantId: "mch_01",
    spendLimit: 25000,
    currency: "USD",
    categoryLock: "advertising",
  }

  it("accepts a well-formed request and trims the nickname", () => {
    const result = parseIssueCardInput({ ...valid, nickname: "  Ad spend  " })
    expect(result).toEqual({
      ok: true,
      value: {
        nickname: "Ad spend",
        merchantId: "mch_01",
        spendLimit: 25000,
        currency: "USD",
        categoryLock: "advertising",
      },
    })
  })

  it("treats a missing or empty category as no lock", () => {
    const { categoryLock: _drop, ...noCategory } = valid
    expect(parseIssueCardInput(noCategory)).toMatchObject({
      ok: true,
      value: { categoryLock: null },
    })
    expect(parseIssueCardInput({ ...valid, categoryLock: "" })).toMatchObject({
      ok: true,
      value: { categoryLock: null },
    })
    expect(parseIssueCardInput({ ...valid, categoryLock: null })).toMatchObject({
      ok: true,
      value: { categoryLock: null },
    })
  })

  it("rejects a body that is not an object", () => {
    expect(parseIssueCardInput(null)).toMatchObject({ ok: false })
    expect(parseIssueCardInput("nope")).toMatchObject({ ok: false })
    expect(parseIssueCardInput([valid])).toMatchObject({ ok: false })
  })

  it("rejects a missing nickname", () => {
    expect(parseIssueCardInput({ ...valid, nickname: "" })).toEqual({
      ok: false,
      error: "Give the card a nickname.",
    })
    expect(parseIssueCardInput({ ...valid, nickname: "   " })).toMatchObject({
      ok: false,
    })
    expect(parseIssueCardInput({ ...valid, nickname: 42 })).toMatchObject({
      ok: false,
    })
  })

  it("rejects an over-long nickname", () => {
    expect(
      parseIssueCardInput({ ...valid, nickname: "x".repeat(41) }),
    ).toMatchObject({ ok: false })
  })

  it("rejects a missing merchant", () => {
    const { merchantId: _drop, ...noMerchant } = valid
    expect(parseIssueCardInput(noMerchant)).toEqual({
      ok: false,
      error: "Choose a merchant.",
    })
    expect(parseIssueCardInput({ ...valid, merchantId: "" })).toMatchObject({
      ok: false,
    })
  })

  it("rejects an unknown merchant", () => {
    expect(parseIssueCardInput({ ...valid, merchantId: "mch_99" })).toEqual({
      ok: false,
      error: "That merchant does not exist.",
    })
  })

  it("rejects a zero or negative limit", () => {
    expect(parseIssueCardInput({ ...valid, spendLimit: 0 })).toEqual({
      ok: false,
      error: "Spend limit must be greater than zero.",
    })
    expect(parseIssueCardInput({ ...valid, spendLimit: -1 })).toMatchObject({
      ok: false,
    })
  })

  it("rejects a limit above 5,000,000 minor units and accepts the ceiling", () => {
    expect(
      parseIssueCardInput({ ...valid, spendLimit: MAX_SPEND_LIMIT + 1 }),
    ).toEqual({
      ok: false,
      error: "Spend limit cannot exceed $50,000.00.",
    })
    expect(
      parseIssueCardInput({ ...valid, spendLimit: MAX_SPEND_LIMIT }),
    ).toMatchObject({ ok: true })
  })

  it("rejects a limit that is not an integer number", () => {
    expect(parseIssueCardInput({ ...valid, spendLimit: 250.5 })).toMatchObject({
      ok: false,
    })
    expect(parseIssueCardInput({ ...valid, spendLimit: "25000" })).toMatchObject(
      { ok: false },
    )
    expect(parseIssueCardInput({ ...valid, spendLimit: NaN })).toMatchObject({
      ok: false,
    })
    expect(
      parseIssueCardInput({ ...valid, spendLimit: Infinity }),
    ).toMatchObject({ ok: false })
  })

  it("rejects a currency outside USD, EUR, GBP", () => {
    expect(parseIssueCardInput({ ...valid, currency: "CHF" })).toEqual({
      ok: false,
      error: "Currency must be USD, EUR, or GBP.",
    })
    expect(parseIssueCardInput({ ...valid, currency: "usd" })).toMatchObject({
      ok: false,
    })
    expect(parseIssueCardInput({ ...valid, currency: undefined })).toMatchObject(
      { ok: false },
    )
  })

  it("rejects a category outside the allowlist", () => {
    expect(
      parseIssueCardInput({ ...valid, categoryLock: "gambling" }),
    ).toEqual({ ok: false, error: "Choose a category from the list." })
    for (const category of CARD_CATEGORIES) {
      expect(
        parseIssueCardInput({ ...valid, categoryLock: category }),
      ).toMatchObject({ ok: true })
    }
  })
})

describe("parseStatusInput", () => {
  it("accepts each status on the allowlist", () => {
    for (const status of CARD_STATUSES) {
      expect(parseStatusInput({ status })).toEqual({ ok: true, value: status })
    }
  })

  it("rejects anything else", () => {
    expect(parseStatusInput({ status: "deleted" })).toMatchObject({ ok: false })
    expect(parseStatusInput({ status: "ACTIVE" })).toMatchObject({ ok: false })
    expect(parseStatusInput({})).toMatchObject({ ok: false })
    expect(parseStatusInput(null)).toMatchObject({ ok: false })
  })
})
